'use strict';
const meetings=[
{id:1,title:'Запуск «Ромашки»: платёжный провайдер',date:'2 ноября · 10:00',duration:'32 минуты',people:['Анна Волкова','Михаил Орлов','Елена Ли'],topic:'Платежи',summary:'Команда выбрала ЮKassa для первого запуска магазина. Пилот начнётся после проверки возвратов. Выпуск остаётся на 12 ноября; главный риск — срок согласования договора.',decisions:['Запустить пилот с ЮKassa на тестовом магазине.','Не включать оплату частями в первый релиз.'],tasks:['Проверить возврат платежа · Михаил · 4 ноября','Согласовать договор · Анна · 5 ноября'],transcript:'10:03 · Анна: Для первого запуска нужен один провайдер.\n\n10:05 · Михаил: У ЮKassa уже проверена интеграция. Остались возвраты.\n\n10:09 · Елена: Тогда оплату частями отложим.\n\n10:12 · Анна: Договор согласую до пятого ноября.',analysis:'Риск: договор может задержать пилот. Следующая проверка — 5 ноября. Это заранее написанный демонстрационный разбор, не ответ модели.'},
{id:2,title:'Каталог: подготовка к пилоту',date:'30 октября · 14:30',duration:'24 минуты',people:['Елена Ли','Михаил Орлов'],topic:'Каталог',summary:'Для пилота отобрали 40 товаров. Фотографии и описания проверим перед публикацией.',decisions:['Открыть пилот на 40 товарах.'],tasks:['Проверить фотографии · Елена · 3 ноября'],transcript:'14:32 · Елена: Предлагаю начать с сорока товаров.\n\n14:34 · Михаил: Согласен, проверим изображения до запуска.',analysis:'Состав пилота согласован. Остаётся проверить материалы.'},
{id:3,title:'Доставка: встреча с командой',date:'29 октября · 11:00',duration:'18 минут',people:['Анна Волкова'],topic:'Доставка',error:true,summary:'',decisions:[],tasks:[],transcript:'11:02 · Анна: Нужно согласовать сроки доставки для пилота.',analysis:''}
];
const names={today:'Сегодня',archive:'Встречи',tasks:'Задачи',memory:'Память',settings:'Настройки'};
let page='archive',selected=1,query='',depth='Резюме',mobileDetail=false,done=new Set(),compact=false,noticeTimer;
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
function notify(message){$('#notice').textContent=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').textContent='',4500)}
function go(target){page=target;mobileDetail=false;render();$('#main').focus()}
function taskMarkup(m,i){const key=`${m.id}-${i}`;return `<label class="task"><input type="checkbox" data-task="${key}" ${done.has(key)?'checked':''}><span>${esc(m.tasks[i])}</span></label>`}
function openMeeting(id){selected=Number(id);page='archive';depth='Резюме';mobileDetail=true;render();$('.detail').focus()}
function meetingButton(m){return `<button class="meeting" style="padding:${compact?10:18}px" data-meeting="${m.id}" aria-pressed="${selected===m.id}"><span class="meta">${m.date} · ${m.duration}</span><strong>${esc(m.title)}</strong><span class="state ${m.error?'warn':''}">${m.error?'⚠ Обработка не завершена':'✓ Результат готов'}</span><div class="meta">${m.people.length} участника · ${m.tasks.length} задачи</div></button>`}
function detail(){const m=meetings.find(m=>m.id===selected);return `${button('← К результатам поиска','back','back')}<div class="row between"><span class="meta">${m.date} · ${m.duration}</span>${button('Переименовать','rename')}</div><h2 style="margin-top:16px">${esc(m.title)}</h2><div class="row">${m.people.map(p=>`<span class="chip">${p}</span>`).join('')}</div>${m.error?`<div class="callout"><strong>Обработка не завершена</strong><p>Демонстрационный сбой: локальная модель недоступна. Стенограмма сохранена.</p>${button('Почему нельзя повторить?','retry')}</div>`:''}<div class="tabs" aria-label="Глубина чтения">${['Резюме','Минутки','Разбор','Стенограмма'].map(d=>`<button data-depth="${d}" aria-pressed="${d===depth}">${d}</button>`).join('')}</div>${content(m)}<hr style="border:0;border-top:1px solid var(--border);margin:24px 0"><div class="row between"><span class="meta">Вымышленная встреча · демоданные</span>${button('Связи в памяти →','memory')}</div>`}
function content(m){if(depth==='Стенограмма')return `<p style="white-space:pre-wrap">${esc(m.transcript)}</p>`;if(m.error)return '<div class="empty"><h3>Результат пока не собран</h3><p class="muted">Откройте сохранённую стенограмму. Модель в прототипе не подключена.</p></div>';if(depth==='Разбор')return `<p>${esc(m.analysis)}</p>`;return `<p class="summary">${esc(m.summary)}</p><h3>Решения</h3>${m.decisions.map(x=>`<p class="decision">${esc(x)}</p>`).join('')}<h3>Следующие шаги</h3>${m.tasks.map((_,i)=>taskMarkup(m,i)).join('')}${depth==='Минутки'?'<h3>Следующая проверка</h3><p>На планёрке 5 ноября сверить статус задач и сроки пилота.</p>':''}`}
function archive(){return `<div class="heading"><h1>Встречи</h1><p class="muted">От разговора — к решениям и следующим шагам.</p></div><div class="split ${mobileDetail?'mobile-detail':''}"><section class="list-column" aria-label="Архив"><label for="search" class="meta">Поиск по названию, участникам и содержанию</label><div class="search"><input id="search" type="search" placeholder="Например, платежи или Анна" value="${esc(query)}">${button('Сбросить','clear')}</div><div id="results"></div></section><article class="panel detail" tabindex="-1" aria-label="Карточка встречи">${detail()}</article></div>`}
function results(){const q=query.trim().toLocaleLowerCase('ru');const hits=meetings.filter(m=>[m.title,m.summary,m.topic,...m.people,...m.decisions,...m.tasks,m.transcript].join(' ').toLocaleLowerCase('ru').includes(q));$('#results').innerHTML=`<p class="meta" role="status">Найдено встреч: ${hits.length}</p>${hits.length?hits.map(meetingButton).join(''):`<div class="panel empty"><h2>Ничего не найдено</h2><p class="muted">Попробуйте имя участника или другое слово.</p>${button('Показать все встречи','clear')}</div>`}`}
function render(){ $('nav').innerHTML=Object.entries(names).map(([id,name])=>`<button data-page="${id}" ${id===page?'aria-current="page"':''}>${name}</button>`).join('');let html='';if(page==='archive')html=archive();if(page==='today')html=`<div class="heading"><span class="meta">Понедельник, 2 ноября · демонстрационный день</span><h1>Сегодня</h1><p class="muted">Важное из ваших разговоров — в одном месте.</p></div><section class="panel memory"><h2>Готовы к следующей встрече?</h2><p>В этой лаборатории можно изучить результаты. Микрофон, системный звук и модели не подключены.</p>${button('Проверить возможности','record','primary')}</section><h2 style="margin-top:28px">Последние встречи</h2><div class="grid">${meetings.map(meetingButton).join('')}</div>`;if(page==='tasks')html=`<div class="heading"><h1>Следующие шаги</h1><p class="muted">Задачи связаны со встречами. Отметки меняются только в демосессии.</p></div><section class="panel">${meetings.filter(m=>m.tasks.length).map(m=>`<h2>${esc(m.title)}</h2>${m.tasks.map((_,i)=>taskMarkup(m,i)).join('')}<p>${button('Открыть источник','source-'+m.id)}</p>`).join('')}</section>`;if(page==='memory')html=`<div class="heading"><h1>Память встреч</h1><p class="muted">Темы → решения → люди. Каждое решение ведёт к источнику.</p></div><div class="grid">${meetings.map(m=>`<section class="panel"><span class="badge">ТЕМА</span><h2 style="margin-top:18px">${m.topic}</h2><p>${m.error?'Решения ещё не извлечены.':esc(m.decisions[0])}</p><h3>Участники</h3><p class="muted">${m.people.join(', ')}</p>${button('Встреча-источник →','source-'+m.id)}</section>`).join('')}</div><div class="callout">Это навигация по заранее заданным связям, не работающий графовый поиск или ответ нейросети.</div>`;if(page==='settings')html=`<div class="heading"><h1>Настройки прототипа</h1><p class="muted">Настройки приложения на Mac не читаются и не меняются.</p></div><section class="panel"><h2>Внешний вид</h2><div class="setting"><label for="density">Плотность списка<select id="density"><option value="normal">Обычная</option><option value="compact" ${compact?'selected':''}>Компактная</option></select></label><p class="meta">Применяется к карточкам в архиве и на главной.</p></div><div class="setting"><h2>Данные и приватность</h2><p>Все встречи вымышлены. Изменения хранятся только в памяти этой вкладки.</p><p>Облачные модели выключены и не подключаются. Загрузка записей не реализована.</p></div><div class="setting"><h2>Аудио и модели</h2><p>Недоступны в прототипе. Никакого запроса к микрофону или имитации успешной записи.</p>${button('Подробнее','record')}</div></section>`;$('#main').innerHTML=html;if(page==='archive')results();document.documentElement.style.setProperty('--card-padding',compact?'10px':'18px');document.querySelectorAll('.meeting').forEach(el=>el.style.padding=compact?'10px':'18px')}
function modal(kind){const m=meetings.find(m=>m.id===selected);const rename=kind==='rename';$('#dialog-form').innerHTML=`<h2 id="dialog-title">${rename?'Переименовать встречу':kind==='retry'?'Повторная обработка недоступна':'Запись не подключена'}</h2>${rename?`<label for="new-title">Название встречи</label><input id="new-title" name="title" maxlength="120" required value="${esc(m.title)}"><p class="meta">Изменится только название в демосессии.</p>`:`<p>${kind==='retry'?'В прототипе нет локальной модели. Повторное нажатие не запустит обработку; исходная демостенограмма доступна.':'Этот интерфейс проверяет дизайн. Захват звука macOS и MLX не перенесены в Linux. Можно открыть вымышленные встречи и проверить навигацию.'}</p>`}<div class="row"><button value="cancel" formnovalidate>${rename?'Отмена':'Понятно'}</button>${rename?'<button class="primary" value="save">Сохранить</button>':''}</div>`;$('#dialog-form').onsubmit=e=>{if(e.submitter?.value==='save'){const input=$('#new-title');if(!input.value.trim()){e.preventDefault();input.setCustomValidity('Введите название, а не только пробелы.');input.reportValidity();return}m.title=input.value.trim();render();requestAnimationFrame(()=>document.querySelector('[data-action=rename]')?.focus());notify('Название изменено в демосессии')}};if(rename)$('#new-title').oninput=()=>$('#new-title').setCustomValidity('');$('dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)return go(b.dataset.page);if(b.dataset.meeting)return openMeeting(b.dataset.meeting);if(b.dataset.depth){depth=b.dataset.depth;$('.detail').innerHTML=detail();document.querySelector(`[data-depth="${depth}"]`).focus();return}const a=b.dataset.action;if(a==='clear'){query='';results();$('#search').value='';$('#search').focus()}else if(a==='back'){mobileDetail=false;render();document.querySelector(`[data-meeting="${selected}"]`)?.focus()}else if(a==='memory')go('memory');else if(a?.startsWith('source-')){query='';openMeeting(a.slice(7))}else if(['rename','record','retry'].includes(a))modal(a)});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;results()}});
document.addEventListener('change',e=>{if(e.target.dataset.task){e.target.checked?done.add(e.target.dataset.task):done.delete(e.target.dataset.task);notify(e.target.checked?'Задача отмечена в демосессии':'Задача снова открыта')}if(e.target.id==='density'){compact=e.target.value==='compact';notify('Плотность списка изменена')}});
render();
